-- 10. 여운 마포 메이크업 스튜디오: 일반 2, 모델 0; OSM node/357916622
INSERT INTO SHOP (SHOP_ID, CATEGORY_ID, LOGIN_ID, PASSWORD_HASH, NAME, REGION_CODE, ADDRESS, ADDRESS_DETAIL,
    LATITUDE, LONGITUDE, PHONE, DESCRIPTION, NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_SHOP.NEXTVAL, 5, 'demo164_s10', 'CHANGE_ME', '여운 마포 메이크업 스튜디오', '11440', '서울특별시 마포구 와우산로 56', '시연용 가상공간',
    37.5494391, 126.9234294, '02-0000-0000', '마포구에서 편안하게 머무는 여운 마포 메이크업 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
    '시연용 가상 매장입니다. 주소는 지도 시연용이며 실제 입점 정보가 아닙니다. 표시된 전화번호는 연결되지 않는 더미입니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM SHOP WHERE LOGIN_ID = 'demo164_s10');
INSERT INTO TREATMENT (TREATMENT_ID, SHOP_ID, NAME, DESCRIPTION, REGULAR_PRICE, PRICE, LAST_MINUTE_PRICE,
    DURATION_MINUTES, TREATMENT_TYPE, MODEL_CONDITION, PREPARATION_NOTES, PHOTO_NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s10'), '코랄 데일리 메이크업', '원하는 분위기와 일정에 맞춰 색감을 상담합니다. 베이스부터 포인트 표현까지 진행하며 헤어 스타일링은 포함하지 않습니다.', 77000, 69300, 58900,
    60, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s10') AND NAME = '코랄 데일리 메이크업');
